// src/layout.ts
function workspaceLabel(roster) {
  return `squad-${roster.squad}`;
}
function hierarchy(members) {
  const boss = new Map(members.map((member) => [member.name, member.reports_to]));
  const depth = (name, seen = []) => {
    const above = boss.get(name);
    if (above === "user")
      return 0;
    if (!boss.has(above) || seen.includes(above))
      return boss.size;
    return 1 + depth(above, [...seen, name]);
  };
  return members.map((member, index) => ({ member, index, depth: depth(member.name) })).sort((a, b) => a.depth - b.depth || a.index - b.index).map(({ member }) => member);
}
function planLayout(members) {
  return hierarchy(members).map((member, index) => ({ number: index + 1, member: member.name }));
}
function layoutProblems(tabs, members) {
  const problems = [];
  if (!members.length)
    return problems;
  const placed = new Map;
  for (const tab of tabs) {
    if (!placed.has(tab.member))
      placed.set(tab.member, []);
    placed.get(tab.member).push(tab.number);
  }
  for (const member of members) {
    const where = placed.get(member.name) ?? [];
    placed.delete(member.name);
    if (where.length !== 1) {
      problems.push(`member ${repr(member.name)} is in ${where.length} tabs (${where.join(", ") || "none"}); it must be in exactly one`);
    }
  }
  for (const name of placed.keys())
    problems.push(`the layout places ${repr(name)}, who is not a member`);
  const supervisor = hierarchy(members)[0].name;
  if (!tabs.length || tabs[0].member !== supervisor)
    problems.push(`the supervisor ${repr(supervisor)} is not in tab 1`);
  return problems;
}
function tabSteps(tabs, running, wanted) {
  const steps = [];
  let opened = false;
  for (const tab of tabs) {
    if (running.has(tab.member)) {
      if (opened)
        steps.push(["move", tab]);
    } else if (wanted.has(tab.member)) {
      steps.push(["open", tab]);
      opened = true;
    }
  }
  return steps;
}
function layoutLines(tabs, byName) {
  return tabs.map((tab) => `TAB ${tab.number} ${repr(display(byName.get(tab.member)))}: ${tab.member}`);
}
function squadState(h, roster) {
  const found = list(h.query(["workspace", "list"]), "workspaces").filter((workspace) => workspace.label === workspaceLabel(roster));
  if (!found.length)
    return [null, []];
  const ws = text(found[0], "workspace_id");
  const panes = list(h.query(["pane", "list", "--workspace", ws]), "panes").map((pane) => ({
    pane_id: text(pane, "pane_id"),
    label: text(pane, "label"),
    tab_id: text(pane, "tab_id")
  }));
  return [ws, panes];
}
function openTab(h, roster, workspace, member, ws) {
  const cwd = join(workspace, member.cwd);
  const label = display(member);
  let pane;
  if (ws === null) {
    const made = h.created(["workspace", "create", "--cwd", cwd, "--label", workspaceLabel(roster), "--no-focus"]);
    pane = paneOf(made, "workspace create");
    ws = text(field(made, "workspace"), "workspace_id") || pane.split(":")[0];
    h.run(["tab", "rename", text(field(made, "tab"), "tab_id") || `${ws}:t1`, label]);
  } else {
    pane = paneOf(h.created(["tab", "create", "--workspace", ws, "--cwd", cwd, "--label", label, "--no-focus"]), "tab create");
  }
  h.run(["pane", "rename", pane, label]);
  return [ws, pane];
}
function paneOf(made, what) {
  const pane = text(field(made, "root_pane"), "pane_id");
  if (!pane)
    throw new LaunchError(`\`herdr ${what}\` reported no root pane`);
  return pane;
}
function moveToEnd(h, member, pane) {
  const made = h.created(["pane", "move", pane, "--new-tab", "--no-focus"]);
  const tab = text(field(field(made, "move_result"), "created_tab"), "tab_id");
  if (!tab)
    throw new LaunchError(`\`herdr pane move ${pane} --new-tab\` reported no new tab for ${member.name}`);
  h.run(["tab", "rename", tab, display(member)]);
}

// src/agentshell.ts
var AGENT_SHELL_INSTALLER = "https://raw.githubusercontent.com/bdsanxz/agent-shell/main/install.sh";
function agentShellDir() {
  return process.env.AGENT_SHELL_INSTALL_DIR || expandUser("~/.local/bin");
}
function agentShellCommand() {
  return which("agent-shell") ?? join(agentShellDir(), "agent-shell");
}
function agentShellInstalled() {
  return isExecutable(agentShellCommand());
}
function agentShellInstaller() {
  return process.env.AGENT_SHELL_INSTALLER_URL || AGENT_SHELL_INSTALLER;
}
async function installAgentShell() {
  if (agentShellInstalled())
    return null;
  const url = agentShellInstaller();
  const byHand = `\`curl -fsSL ${url} | sh\``;
  if (!which("bun")) {
    fail(`the agent-shell CLI is not installed, and it needs bun on PATH to run; install Bun (https://bun.sh), then run build again`);
  }
  const token = githubToken();
  let script;
  try {
    script = await fetchInstaller(url, token);
  } catch (error) {
    fail(`the agent-shell CLI is not installed, and its install script could not be fetched from ${url}: ${reason(error)}. ` + "A private repository needs GITHUB_TOKEN or a signed-in GitHub CLI (`gh auth login`). " + `Install it by hand with ${byHand}, then run build again`);
  }
  const env = { ...process.env, ...token ? { GITHUB_TOKEN: token } : {} };
  const done = run(["sh", "-s"], { input: script, env });
  const log = strip(done.stdout + done.stderr);
  if (done.code !== 0 || !agentShellInstalled()) {
    fail(`the agent-shell CLI did not install: the install script from ${url} exited ${done.code} and ` + `${agentShellCommand()} is not there. Its output:
${tail(log, 1500)}
` + `Fix the cause, or install it by hand with ${byHand}, then run build again`);
  }
  const version = strip(run([agentShellCommand(), "--version"], { inheritStdin: true }).stdout);
  let line = `INSTALLED ${version || "agent-shell"} at ${agentShellCommand()}`;
  if (!which("agent-shell")) {
    line += `; WARNING ${agentShellDir()} is not on PATH, so members cannot run \`agent-shell\`: add it to PATH in the ` + "shell profile, then restart herdr so the members inherit it";
  }
  return line;
}

